def merge(intervals):
    if not intervals:
        return []
    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0]]
    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    return merged


def free_gaps(intervals, window):
    ws, we = window
    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    gaps = []
    current_start = ws
    for start, end in sorted_intervals:
        # Clip interval to the window
        clipped_start = max(start, ws)
        clipped_end = min(end, we)
        if clipped_start < clipped_end:
            # Add gap before the interval
            if current_start < clipped_start:
                gaps.append((current_start, clipped_start))
            current_start = max(current_start, clipped_end)
    # Add the final gap if any
    if current_start < we:
        gaps.append((current_start, we))
    return gaps


def max_overlap(intervals):
    if not intervals:
        return 0
    # Create a list of events: (start, +1), (end, -1)
    events = []
    for start, end in intervals:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))
    # Sort events by position, and by type (start before end at the same position)
    events.sort(key=lambda x: (x[0], -x[1]))
    max_overlap = 0
    current_overlap = 0
    for pos, change in events:
        current_overlap += change
        max_overlap = max(max_overlap, current_overlap)
    return max_overlap

